/**
 * TEMPORARY PLACEHOLDER IMAGERY.
 *
 * 1. Lifestyle photos — free stock photos from Unsplash (https://unsplash.com/license), used
 *    only for campaign / category / gallery areas. They do not show JYGS products.
 *    Selection rules: plain T-shirts only, no visible third-party logos, slogans or graphics,
 *    neutral backgrounds.
 * 2. Product artwork — original placeholder SVG illustrations generated by
 *    `scripts/generate-placeholder-tees.mjs` (captioned "PLACEHOLDER ARTWORK").
 *
 * Replace both with the owner's real photography (brief §15).
 */
export const stockPhotoIds = {
  whiteTeeModel: "1521572163474-6864f9cf17ab",
  manWhiteTeeStudio: "1586790170083-2f9ceadc732d",
  manWhiteTeeCap: "1622445275463-afa2ab738c34",
  whiteTeeHanger: "1581655353564-df123a1eb820",
  womanWhiteTee: "1580489944761-15a19d654956",
  womanBlackTee: "1567532939604-b6b5b0db2604",
  womanBlackTeeWall: "1499952127939-9bbf5af6c51c",
  manBlackTeeShades: "1618517351616-38fb9c5210c6",
  manBlackTeeWall: "1622519407650-3df9883f76a5",
  blackTeesHangers: "1610502778270-c5c6f4c7d575",
  blackRack: "1529720317453-c8da503f2051",
} as const;

export type StockPhotoKey = keyof typeof stockPhotoIds;

/** Builds a pre-cropped Unsplash URL. `next/image` then resizes and converts it to AVIF/WebP. */
export function stockPhoto(key: StockPhotoKey, width = 1600): string {
  return `https://images.unsplash.com/photo-${stockPhotoIds[key]}?auto=format&fit=crop&w=${width}&q=80`;
}

/** JYGS colourway slugs used by the placeholder tee artwork. */
export type TeeColour =
  "black" | "off-white" | "white" | "cherry" | "pine-green" | "me-lavender" | "plum";

/** Back-graphic placeholder styles available in the generated artwork. */
export type BackGraphic = "stack" | "orbit" | "monogram" | "repeat";

/** Path to a generated placeholder tee illustration (served from /public, unoptimised SVG). */
export function teeArt(colour: TeeColour, view: "front"): string;
export function teeArt(colour: TeeColour, view: "back", graphic: BackGraphic): string;
export function teeArt(colour: TeeColour, view: "front" | "back", graphic?: BackGraphic): string {
  return view === "front"
    ? `/demo/tees/tee-${colour}-front.svg`
    : `/demo/tees/tee-${colour}-back-${graphic}.svg`;
}
